/* Signature Tatar Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Ayguzel": "From ay (moon) + guzel (beautiful): 'moon-beautiful'.", "Timurgul": "From timur (iron) + gul (flower): 'iron flower'.", "Ilsugul": "From il (country) + su (water) + gul.", "Nuraygul": "From nur (light) + ay (moon) + gul.", "Bulats": "From bulat (steel).", "Zulfiyagul": "From zulfiya + gul.", "Ayguzelov": "Signature surname in -ov style built on Ayguzel.", "Timurgulyev": "Signature surname in -ev style built on Timurgul.", "Nurgaliyev": "Signature surname from nur + gali in -ev style.", "Guzelov": "Signature surname in -ov style built on Guzel."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Ayguzel';
console.log(lookup(q));

